  "content": "import re, sys, time, gzip, urllib.request
from datetime import datetime, timedelta
from pathlib import Path

D = Path(__file__).resolve().parent.parent
T0, T1 = datetime(2025, 10, 15), datetime(2025, 12, 6)


def get(url, tries=8, minsize=0):
    for k in range(tries):
        try:
            with urllib.request.urlopen(urllib.request.Request(url, headers={"User-Agent": "Mozilla/5.0"}), timeout=180) as r:
                b = r.read()
            if len(b) >= minsize and not b[:200].lstrip().lower().startswith((b"<!doctype", b"<html")) or minsize == 0:
                return b
        except Exception as e:
            print("retry", k, url, e, flush=True)
        time.sleep(min(5 * 2 ** k, 120))
    raise RuntimeError(url)


def listing(url, pat):
    return sorted(set(re.findall(pat, get(url).decode("latin1"))))


def days():
    d = T0
    while d <= T1:
        yield d
        d += timedelta(days=1)


def pick(cands):
    out = []
    for d in days():
        c = [x for x in cands if abs((x[0] - d).total_seconds()) <= 12 * 3600]
        if c:
            out.append((d, min(c, key=lambda x: abs((x[0] - d).total_seconds()))))
        else:
            out.append((d, None))
    return out


def gong():
    base = "https://gong.nso.edu/data/magmap/QR/zqs/"
    c = []
    for d in list(days()) + [T0 - timedelta(days=1)]:
        u = f"{base}{d:%Y%m}/mrzqs{d:%y%m%d}/"
        for f in listing(u, r'href="(mrzqs\d{6}t\d{4}c\d{4}_\d{3}\.fits\.gz)"'):
            m = re.match(r"mrzqs(\d{6})t(\d{4})", f)
            c.append((datetime.strptime(m[1] + m[2], "%y%m%d%H%M"), u + f))
    return c


def adapt():
    base = "https://gong.nso.edu/adapt/maps/gong/2025/"
    c = []
    for f in listing(base, r'href="(adapt4\d+_\d+_(\d{12})_\w+\.fts\.gz)"'):
        c.append((datetime.strptime(f[1], "%Y%m%d%H%M"), base + f[0]))
    return c


def wsa():
    base = "https://iswa.gsfc.nasa.gov/iswa_data_tree/model/solar/WSA5.4/R21.5/WSA_OUT/GONG_Z/"
    c = []
    for ym in ["2025/10/", "2025/11/", "2025/12/"]:
        for f in listing(base + ym, r'href="(wsa_(\d{12})R000_gong_z\.fits)"'):
            c.append((datetime.strptime(f[1], "%Y%m%d%H%M"), base + ym + f[0]))
    return c


def run(name, fn, sub, minsize):
    out = D / sub
    rows = []
    for d, x in pick(fn()):
        if x is None:
            print(name, d.date(), "missing", flush=True)
            rows.append((d, None, None))
            continue
        p = out / x[1].rsplit("/", 1)[1]
        if not p.exists() or p.stat().st_size < minsize:
            p.write_bytes(get(x[1], minsize=minsize))
        print(name, d.date(), p.name, p.stat().st_size, flush=True)
        rows.append((d, p.name, x[1]))
    (out / "fetch_log.csv").write_text("target_date,file,url\n" + "".join(f"{d:%Y-%m-%d},{f or ''},{u or ''}\n" for d, f, u in rows))


if __name__ == "__main__":
    for s in sys.argv[1:]:
        run(s, {"gong": gong, "adapt": adapt, "wsa": wsa}[s], {"gong": "gong", "adapt": "adapt", "wsa": "wsa_ccmc"}[s], {"gong": 100000, "adapt": 1000000, "wsa": 300000}[s])
"
}

